import java.util.*;

class Solution {
  public List<Integer> longestCommonSubsequence(int[][] arrays) {
    // each array is strictly increasing, so the answer is the values present in every array, in order
    int[] count = new int[101];
    for (int[] a : arrays) for (int x : a) count[x]++;
    List<Integer> res = new ArrayList<>();
    for (int v = 1; v <= 100; v++) if (count[v] == arrays.length) res.add(v);
    return res;
  }
}
